import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faChalkboardTeacher, faUserGraduate, faCalendarAlt, faBell } from '@fortawesome/free-solid-svg-icons';
import './../assets/css/dashboard-content.css';

const DashboardContent = () => {
  const [totalStudents, setTotalStudents] = useState(0);
  const [totalTeachers, setTotalTeachers] = useState(0);
  const [upcomingEvents, setUpcomingEvents] = useState(0);
  const [activeCourses, setActiveCourses] = useState(0);

  useEffect(() => {
    fetchSummaryData();
  }, []);

  const fetchSummaryData = async () => {
    try {
      const token = localStorage.getItem('token');

      const studentsRes = await axios.get('http://localhost:5000/api/students', {
        headers: { 'x-auth-token': token }
      });
      setTotalStudents(studentsRes.data.length);

      const teachersRes = await axios.get('http://localhost:5000/api/teachers', {
        headers: { 'x-auth-token': token }
      });
      setTotalTeachers(teachersRes.data.length);

      // Placeholder for fetching other data
      setUpcomingEvents(12); 
      setActiveCourses(45);

    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="dashboard-content">
      <div className="dashboard-header">
        <div>
          <h2>Welcome Back, Admin!</h2>
          <p>Here's your dashboard overview for September.</p>
        </div>
      </div>

      <div className="stats-grid">
        <div className="stat-card">
          <h3>Total Students</h3>
          <p>{totalStudents}</p>
        </div>
        <div className="stat-card">
          <h3>Total Teachers</h3>
          <p>{totalTeachers}</p>
        </div>
        <div className="stat-card">
          <h3>Upcoming Events</h3>
          <p>{upcomingEvents}</p>
        </div>
        <div className="stat-card">
          <h3>Active Courses</h3>
          <p>{activeCourses}</p>
        </div>
      </div>

      <div className="dashboard-grid">
        <div className="calendar-card">
          <h3>September 2025</h3>
          {/* Calendar placeholder */}
          <div className="quick-actions">
            <button>Add New Event</button>
            <button>Send Announcement</button>
          </div>
        </div>

        <div className="events-card">
          <h3>Upcoming Events</h3>
          <ul>
            <li>
              <span>May 10th - Parent-Teacher Conference</span>
              <span className="event-tag event">Event</span>
            </li>
            <li>
              <span>May 15th - Science Fair Judging</span>
              <span className="event-tag event">Event</span>
            </li>
            <li>
              <span>May 20th - Midterm Exams Begin</span>
              <span className="event-tag exam">Exam</span>
            </li>
            <li>
              <span>May 27th - Memorial Day</span>
              <span className="event-tag holiday">Holiday</span>
            </li>
          </ul>
        </div>
      </div>

      <div className="charts-grid">
        <div className="chart-card">
          <h3>Enrollment by Grade</h3>
          {/* Chart Placeholder */}
        </div>
        <div className="chart-card">
          <h3>Teacher Distribution</h3>
          {/* Chart Placeholder */}
        </div>
      </div>
    </div>
  );
};

export default DashboardContent;
